sqlite3 -header ../data/current.db "
select distinct measured_at_ms, pool_id from telemetry_samples where measured_at_ms between 1778112000000 and 1778119200000 order by 1;
select count(*) from telemetry_samples t join worker_pools p on p.pool_id=t.pool_id where p.pool_code like 'sync%';
select min(measured_at_ms), max(measured_at_ms) from telemetry_samples;
select count(*), min(opened_at_ms), max(opened_at_ms) from logical_operations;
"

sqlite3 -header ../data/current.db "
select pool_id, signal_id, measured_at_ms, value from telemetry_samples where measured_at_ms between 1778100000000 and 1778120000000 order by measured_at_ms limit 40;
select distinct measured_at_ms from telemetry_samples where measured_at_ms between 1778100000000 and 1778125000000 order by 1;
"

sqlite3 -header ../data/current.db "
select distinct measured_at_ms, datetime(measured_at_ms/1000,'unixepoch') from telemetry_samples where measured_at_ms>1778000000000 order by 1;
"
